using System;using System.IO;using System.Drawing;using System.Linq;using System.Text;using System.IO.Compression;using System.Security.Cryptography;using System.Threading.Tasks;using System.Collections.Generic;using System.Windows.Forms;
internal sealed partial class ControlWindow {
 async Task WaitCoverDialog(){for(int i=0;i<200&&(importDialog==null||importOperation==null||importOperation.Busy);i++)await Task.Delay(50);Require(importDialog!=null&&importOperation!=null&&!importOperation.Busy,"Cover dialog not ready");}
 List<ImportCandidate> CoverCandidates(Dictionary<string,object> data){return Common.Json.Deserialize<List<ImportCandidate>>(Common.Json.Serialize(data["candidates"]));}
 internal async Task RunCoverSmoke(string mode){try{
  if(mode=="scratch"){var scan=await ImportJob("scan",null,null);var candidate=CoverCandidates(scan).Single(x=>x.Id=="395417");Require(candidate.Cover!=null,"Cold cache commit failed");Require(!Directory.GetFiles(Path.Combine(importOperation.Folder,"cover-temp")).Any(),"Successful cover temp residue");Common.SaveNew(Path.Combine(Common.Root,"evidence/scratch-cold.json"),scan);string fixture=Path.Combine(Common.Root,"tests","scratch-fixture");Directory.CreateDirectory(Path.Combine(fixture,"cache_info"));Directory.CreateDirectory(Path.Combine(fixture,"wallpaper","wpcache","dynamic"));File.Copy(candidate.Source,Path.Combine(fixture,"wallpaper","wpcache","dynamic",candidate.Md5+".cwp"));FixtureRecord(Path.Combine(fixture,"cache_info"),"395417",candidate.Md5);File.WriteAllText(Path.Combine(Common.Root,"tests","import-root.txt"),fixture);var task=ImportJob("scan",null,null,60);string scratch=Path.Combine(importOperation.Folder,"cover-temp");Directory.CreateDirectory(scratch);File.WriteAllText(Path.Combine(scratch,"partial-test.tmp"),"owned test scratch");await Task.Delay(150);importOperation.Cancel();try{await task;}catch(OperationCanceledException){}Require(!Directory.Exists(scratch),"Cancelled cover scratch retained");Common.SaveNew(Path.Combine(Common.Root,"evidence/scratch-passed.json"),new{coldCommit=true,cancelledScratchRemoved=true,noPlayer=CurrentRun==null});Close();return;}
  if(mode=="layout"){OpenLocalImport();await WaitCoverDialog();var c=Common.Read(Path.Combine(importOperation.Folder,"result.json"));Require(c.ContainsKey("coverStats"),"Layout scan was cancelled before evidence capture");Require(Convert.ToInt64(Common.Obj(c["coverStats"])["hashedBytes"])==0,"Restart lost cache");Common.SaveNew(Path.Combine(Common.Root,"evidence/cover-restart-cache-release.json"),c);foreach(ListViewItem row in importDialog.list.Items)if(((ImportCandidate)row.Tag).Id=="395417"){row.Selected=true;row.EnsureVisible();break;}ClientShot(importDialog,"covers-dialog-release");importDialog.Size=importDialog.MinimumSize;foreach(ListViewItem row in importDialog.list.Items)if(((ImportCandidate)row.Tag).Id=="28987"){row.Selected=true;row.EnsureVisible();break;}ClientShot(importDialog,"covers-dialog-small-release");importDialog.Close();await Task.Delay(1200);Close();return;}
  if(mode=="interface"){
   OpenLocalImport();await WaitCoverDialog();await Task.Delay(100);var first=Common.Read(Path.Combine(importOperation.Folder,"result.json"));var found=CoverCandidates(first);var target=found.Single(x=>x.Id=="395417");Require(target.Cover!=null&&target.CoverSourceSha256=="834991b4d9e1c0309492c096abb7217077d1a4a04cd4985732e2e216f67e62c6","Real v2 cover binding");Require(found.Single(x=>x.Id=="366396").Cover==null,"Unknown v3 must remain placeholder");
   Common.SaveNew(Path.Combine(Common.Root,"evidence/cover-first-scan.json"),first);
   foreach(ListViewItem row in importDialog.list.Items)if(((ImportCandidate)row.Tag).Id=="395417"){row.Selected=true;row.EnsureVisible();break;}
   ClientShot(importDialog,"covers-dialog");await importDialog.Scan();var repeat=Common.Read(Path.Combine(importOperation.Folder,"result.json"));var stats=Common.Obj(repeat["coverStats"]);Require(Convert.ToInt64(stats["hashedBytes"])==0&&Convert.ToInt32(stats["previewMembersRead"])==0,"Refresh reread large source or redecoded preview");Common.SaveNew(Path.Combine(Common.Root,"evidence/cover-repeat-scan.json"),repeat);
   importDialog.Size=importDialog.MinimumSize;importDialog.list.Items[importDialog.list.Items.Count-1].EnsureVisible();ClientShot(importDialog,"covers-dialog-small-scrolled");importDialog.Close();ClientShot(this,"covers-home");Common.SaveNew(Path.Combine(Common.Root,"evidence/cover-interface-passed.json"),new{cards=library.Doc.Items.Count,covered=found.Where(c=>c.Cover!=null).Select(c=>c.Id).ToArray(),uncovered=found.Where(c=>c.Cover==null).Select(c=>new{id=c.Id,reason=c.CoverReason}).ToArray(),autoPlayed=CurrentRun!=null,method="internal own UI handlers, PrintWindow; no injected input"});await Task.Delay(1200);Close();return;
  }
  if(mode=="isolated"){
   var first=await ImportJob("scan",null,null);var c=CoverCandidates(first).Single(x=>x.Id=="395417");var data=await ImportJob("copy",c,null);bool duplicate;var item=RegisterImport(importOperation,data,out duplicate);Require(!duplicate&&item.PreviewConfirmedSha256==null&&item.DesktopConfirmedSha256==null&&CurrentRun==null,"Cover imported compatibility/autoplay");Require(File.Exists(item.CoverPath)&&LocalImport.Under(item.SourcePath,Path.Combine(Common.Root,"library")),"Private source/cover missing");SelectWallpaper(item);ClientShot(this,"cover-imported-card");Common.SaveNew(Path.Combine(Common.Root,"evidence/cover-import-result.json"),new{item=item,receipt=data,autoPlayed=false,formatPolicy=CwpPolicy.Validate(item.SourcePath,item.RegisteredSha256)});
   string fixture=Path.Combine(Common.Root,"tests","cover-fixtures"),records=Path.Combine(fixture,"cache_info"),files=Path.Combine(fixture,"wallpaper","wpcache","dynamic");Directory.CreateDirectory(records);Directory.CreateDirectory(files);File.WriteAllText(Path.Combine(Common.Root,"tests","import-root.txt"),fixture);
   string source=Path.Combine(files,c.Md5+".cwp");File.Copy(c.Source,source);FixtureRecord(records,"395417",c.Md5);
   FixturePackage(records,files,"99901",Encoding.ASCII.GetBytes(new String('x',120)));
   byte[] huge=new byte[32];new byte[]{137,80,78,71,13,10,26,10}.CopyTo(huge,0);Encoding.ASCII.GetBytes("IHDR").CopyTo(huge,12);huge[16]=1;huge[20]=1;FixturePackage(records,files,"99902",huge);
   FixturePackage(records,files,"99903",new byte[9*1048576]);
   var fixtureResult=await ImportJob("scan",null,null);var all=CoverCandidates(fixtureResult);Require(all.Single(x=>x.Id=="395417").Cover!=null,"Good sibling lost");foreach(var id in new[]{"99901","99902","99903"})Require(all.Single(x=>x.Id==id).Cover==null&&!String.IsNullOrEmpty(all.Single(x=>x.Id==id).CoverReason),"Invalid image budget/fallback failed");Common.SaveNew(Path.Combine(Common.Root,"evidence/cover-invalid-images.json"),fixtureResult);
   DateTime saved=File.GetLastWriteTimeUtc(source);using(var f=new FileStream(source,FileMode.Open,FileAccess.ReadWrite)){f.Position=f.Length-1;int v=f.ReadByte();f.Position--;f.WriteByte((byte)(v^1));}File.SetLastWriteTimeUtc(source,saved);var changed=await ImportJob("scan",null,null);var changedItem=CoverCandidates(changed).Single(x=>x.Id=="395417");Require(changedItem.Cover==null&&changedItem.CoverReason.Contains("MD5"),"Same-size/restored-mtime content reused old cover");Common.SaveNew(Path.Combine(Common.Root,"evidence/cover-source-changed.json"),changed);
   File.Delete(source);File.Copy(c.Source,source);var slow=ImportJob("scan",null,null,60);await Task.Delay(150);importOperation.Cancel();bool cancelled=false;try{await slow;}catch(OperationCanceledException){cancelled=true;}Require(cancelled&&!importOperation.Busy,"Cover scan cancellation failed");Common.SaveNew(Path.Combine(Common.Root,"evidence/cover-cancel-passed.json"),new{cancelled=true,playerNeverStarted=CurrentRun==null});
   // A corrupt private thumbnail also falls back without rehashing the large source.
   File.Delete(source);File.Copy(c.Source,source);var fresh=await ImportJob("scan",null,null);var good=CoverCandidates(fresh).Single(x=>x.Id=="395417");byte[] thumbnail=File.ReadAllBytes(good.Cover);File.WriteAllText(good.Cover,"broken private image");var broken=await ImportJob("scan",null,null);Require(CoverCandidates(broken).Single(x=>x.Id=="395417").Cover==null,"Corrupt thumbnail used");File.WriteAllBytes(good.Cover,thumbnail);Common.SaveNew(Path.Combine(Common.Root,"evidence/cover-cache-damage.json"),broken);
   File.Delete(source);File.Copy(c.Source,source);var closeTask=ImportJob("scan",null,null,60);await Task.Delay(150);Common.SaveNew(Path.Combine(Common.Root,"evidence/cover-isolated-passed.json"),new{importedId="395417",cards=library.Doc.Items.Count,negativeFixtures=true,sourceIdentityInvalidation=true,closeDuringCoverScan=true,noPlayer=CurrentRun==null});Close();try{await closeTask;}catch{}return;
  }
  throw new ArgumentException(mode);
 }catch(Exception ex){Write("cover-smoke-failed",new{error=ex.ToString()});}Close();}
 void FixtureRecord(string dir,string id,string md5){byte[] b=Encoding.UTF8.GetBytes("0000"+Common.Json.Serialize(new{wpId=Int32.Parse(id),wpName=md5+".cwp",wpMd5=md5,wpType=2}));for(int i=0;i<b.Length;i++)b[i]^=0xe7;File.WriteAllBytes(Path.Combine(dir,id+"_test.dat"),b);}
 byte[] FixtureEncrypt(byte[] b){byte[] p=Encoding.ASCII.GetBytes("123"),s,m,key,iv;using(var h=SHA256.Create())s=h.ComputeHash(p);using(var h=MD5.Create()){m=h.ComputeHash(p);key=h.ComputeHash(s.Concat(m).ToArray());iv=h.ComputeHash(s);}using(var a=Aes.Create()){a.Key=key;a.IV=iv;a.Padding=PaddingMode.PKCS7;using(var e=a.CreateEncryptor())return e.TransformFinalBlock(b,0,b.Length);}}
 void FixturePackage(string records,string files,string id,byte[] image){byte[] compressed;using(var s=new MemoryStream()){using(var z=new DeflateStream(s,CompressionMode.Compress,true))z.Write(image,0,image.Length);compressed=s.ToArray();}byte[] payload=FixtureEncrypt(compressed),name=Encoding.UTF8.GetBytes("preview.jpg"),table;using(var s=new MemoryStream())using(var w=new BinaryWriter(s)){w.Write(1);w.Write(0);w.Write(payload.Length);w.Write(0);w.Write(name.Length);w.Write(name);table=FixtureEncrypt(s.ToArray());}int start=16+table.Length;byte[] package;using(var s=new MemoryStream())using(var w=new BinaryWriter(s)){w.Write(0x02505743);w.Write(start+payload.Length);w.Write(table.Length);w.Write(start);w.Write(table);w.Write(payload);package=s.ToArray();}string md5;using(var h=MD5.Create())md5=BitConverter.ToString(h.ComputeHash(package)).Replace("-","").ToLowerInvariant();File.WriteAllBytes(Path.Combine(files,md5+".cwp"),package);FixtureRecord(records,id,md5);}
}
